Node* find_closest_node(const Graph& graph, float x, float y) 
{
    Node* closest_node = nullptr;
    float min_distance = std::numeric_limits<float>::max();

    // Iterate over all nodes in the graph
    for (auto& node : graph.SNodes())
    {
        // Check if the node is associated with any non-footway roads
        bool is_footway = true;
        auto& roads = graph.get_node_to_roadmap().at(node.index_);
        for (const auto& road : roads)
        {
            if (road->type != Model::Road::Type::Footway)
            {
                is_footway = false;
                break;
            }
        }

        // Skip footway nodes
        if (is_footway)
        {
            continue;
        }

        // Calculate Euclidean distance
        float dx = node.x - x;
        float dy = node.y - y;
        float distance = std::sqrt(dx * dx + dy * dy);

        // Update closest node if this node is closer
        if (distance < min_distance)
        {
            min_distance = distance;
            closest_node = &node;
        }
    }

    return closest_node;
}

